import{b as e,O as d,g as o,j as r}from"./chunks/framework.DcaUmd3X.js";const p=JSON.parse('{"title":"VSCode 管理代码","description":"","frontmatter":{},"headers":[],"relativePath":"git/collaboration/vscode/index.md","filePath":"Git操作手册/4.协作与进阶/04.VSCode管理代码.md","lastUpdated":1781406415000}'),a={name:"git/collaboration/vscode/index.md"};function i(l,t,s,c,n,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="vscode-管理代码" tabindex="-1">VSCode 管理代码 <a class="header-anchor" href="#vscode-管理代码" aria-label="Permalink to &quot;VSCode 管理代码&quot;">​</a></h1><blockquote><p>不用终端也能操作 Git——VS Code 的图形界面和常用插件</p></blockquote><h2 id="命令行和-vs-code-不冲突" tabindex="-1">命令行和 VS Code 不冲突 <a class="header-anchor" href="#命令行和-vs-code-不冲突" aria-label="Permalink to &quot;命令行和 VS Code 不冲突&quot;">​</a></h2><p>前面所有章都是用终端敲命令。这章讲 VS Code 里的 Git 操作，不是为了替代命令行——而是两个配合着用。有些事 VS Code 做得更好（比如可视化冲突解决），有些事命令行更快（比如 <code>git rebase -i</code>）。</p><h2 id="用-vs-code-打开一个-git-仓库" tabindex="-1">用 VS Code 打开一个 Git 仓库 <a class="header-anchor" href="#用-vs-code-打开一个-git-仓库" aria-label="Permalink to &quot;用 VS Code 打开一个 Git 仓库&quot;">​</a></h2><p>VS Code 不需要额外配置 Git——只要电脑上装了 Git，VS Code 会自动识别。打开项目文件夹后，左侧活动栏的第三个图标就是<strong>源代码管理</strong>（Source Control，快捷键 <code>Ctrl+Shift+G</code>）。</p><p>图标上的数字表示当前有多少文件有改动。点击打开面板，你会看到两个区域：</p><ul><li><strong>Changes</strong>（更改）— 工作区里有修改、Git 还没跟踪的文件。对应终端的 <code>git status</code></li><li><strong>Staged Changes</strong>（暂存的更改）— 已经 <code>git add</code> 了的文件</li></ul><h2 id="vs-code-操作-↔-git-命令对照" tabindex="-1">VS Code 操作 ↔ Git 命令对照 <a class="header-anchor" href="#vs-code-操作-↔-git-命令对照" aria-label="Permalink to &quot;VS Code 操作 ↔ Git 命令对照&quot;">​</a></h2><p>所有操作都可以用鼠标完成，不需要记快捷键：</p><table tabindex="0"><thead><tr><th>操作</th><th>VS Code 怎么做</th><th>终端命令</th></tr></thead><tbody><tr><td>查看改动</td><td>源代码管理面板，点击文件</td><td><code>git status</code> / <code>git diff</code></td></tr><tr><td>加入暂存区</td><td>文件右侧点 <code>+</code> 按钮</td><td><code>git add</code></td></tr><tr><td>暂存所有文件</td><td>Changes 标题右侧点 <code>+</code></td><td><code>git add .</code></td></tr><tr><td>取消暂存</td><td>Staged Changes 区文件右侧点 <code>-</code></td><td><code>git restore --staged</code></td></tr><tr><td>提交</td><td>顶部输入框写信息，点 <code>✔</code> 或 <code>Ctrl+Enter</code></td><td><code>git commit -m &quot;&quot;</code></td></tr><tr><td>丢弃修改</td><td>文件右侧点 ↩ 图标</td><td><code>git restore 文件名</code></td></tr><tr><td>推送</td><td>底部状态栏点 🔄 图标</td><td><code>git push</code></td></tr><tr><td>拉取</td><td>底部状态栏点 🔄 图标</td><td><code>git pull</code></td></tr></tbody></table><blockquote><p>💡 在 VS Code 里点击改动文件，会自动打开<strong>左右对比视图</strong>——左边是旧版本，右边是你改的版本。比命令行里的 <code>+</code> <code>-</code> 符号直观十倍。</p></blockquote><h2 id="切换和创建分支" tabindex="-1">切换和创建分支 <a class="header-anchor" href="#切换和创建分支" aria-label="Permalink to &quot;切换和创建分支&quot;">​</a></h2><p>VS Code 底部状态栏左侧显示当前分支名。点击它：</p><ul><li>弹出分支列表，点击任意分支直接切换</li><li>选择 <strong>Create new branch</strong> 输入名字，等于 <code>git switch -c 新分支名</code></li></ul><p>分支切换后，底部状态栏的分支名会同步更新。</p><h2 id="可视化解决冲突" tabindex="-1">可视化解决冲突 <a class="header-anchor" href="#可视化解决冲突" aria-label="Permalink to &quot;可视化解决冲突&quot;">​</a></h2><p>这是 VS Code 比命令行强最多的地方。文件有冲突时，VS Code 会在冲突区域上方显示三个按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th><th>等于</th></tr></thead><tbody><tr><td><strong>Accept Current Change</strong></td><td>保留你当前的版本</td><td>删掉对方的改动</td></tr><tr><td><strong>Accept Incoming Change</strong></td><td>用对方的版本</td><td>删掉自己的改动</td></tr><tr><td><strong>Accept Both Changes</strong></td><td>两个都保留</td><td>你的在上，对方的在下</td></tr><tr><td><strong>Compare Changes</strong></td><td>左右对比两个版本</td><td>不直接用，先看看</td></tr></tbody></table><p>点击按钮，冲突就解决了——不用手动删 <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>、<code>=======</code>、<code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code> 这些标记。全部解决完后，保存文件 → 在源代码管理面板点 <code>+</code> 暂存 → 提交。</p><h2 id="回滚代码-git-history-插件" tabindex="-1">回滚代码：Git History 插件 <a class="header-anchor" href="#回滚代码-git-history-插件" aria-label="Permalink to &quot;回滚代码：Git History 插件&quot;">​</a></h2><p>VS Code 自带的功能只能看当前状态，要看提交历史需要装插件。推荐 <strong>Git History</strong>：</p><ol><li>在扩展商店搜索 &quot;Git History&quot; 安装</li><li>打开文件，右键 → <strong>Git: View File History</strong></li><li>右侧列出该文件的所有历史提交</li><li>点击某个提交，可以看到当时改了什么</li><li>两个按钮：<strong>Reset --soft</strong> 和 <strong>Reset --hard</strong>，点击即可回退</li></ol><blockquote><p>⚠️ 用 <code>--hard</code> 之前确认一下有没有未提交的改动——它会把工作区也清空，不可恢复。</p></blockquote><h2 id="两个必装插件" tabindex="-1">两个必装插件 <a class="header-anchor" href="#两个必装插件" aria-label="Permalink to &quot;两个必装插件&quot;">​</a></h2><h3 id="gitlens-代码考古神器" tabindex="-1">GitLens：代码考古神器 <a class="header-anchor" href="#gitlens-代码考古神器" aria-label="Permalink to &quot;GitLens：代码考古神器&quot;">​</a></h3><p>GitLens 是 VS Code 最受欢迎的 Git 插件（下载量超 3000 万）。安装后不需要任何配置，打开文件就能看到：</p><ul><li><strong>行内 blame 注解</strong> — 每行代码末尾会显示&quot;谁、什么时候、在哪次提交改的&quot;。光标移到某行，自动弹出详细信息</li><li><strong>悬停查看</strong> — 鼠标放在任意代码上，弹出该行的提交信息和改动时间</li><li><strong>文件历史</strong> — 右键文件 → GitLens: Open File History，看到完整改动时间线</li><li><strong>侧边栏</strong> — 提供 Commit、File History、Branches、Remotes 等面板</li></ul><blockquote><p>💡 排查 bug 时最常用：看到一行有问题的代码 → GitLens 显示它是三个月前张三在某个提交里改的 → 点进去看那次提交还改了什么 → 问题定位。</p></blockquote><h3 id="git-graph-分支可视化" tabindex="-1">Git Graph：分支可视化 <a class="header-anchor" href="#git-graph-分支可视化" aria-label="Permalink to &quot;Git Graph：分支可视化&quot;">​</a></h3><p>Git Graph 把 <code>git log --graph</code> 变成了一张交互式可视化图。安装后在源代码管理面板顶部出现 <strong>Git Graph</strong> 按钮，点击打开：</p><ul><li>每个提交是一个点，分支是不同的颜色线</li><li>点一下提交，右侧展开详细信息（改动文件列表、diff）</li><li>右键提交可以直接 <strong>Cherry Pick</strong>、<strong>Reset</strong>、<strong>Revert</strong>、<strong>Create Branch</strong></li><li>拖动可以创建和合并分支</li></ul><p>相当于把 <code>git log --graph --oneline</code> + 各种 Git 操作做成了 GUI。分支策略那篇画的 ASCII 图，在这里是活的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>命令行和 VS Code 各有擅长的场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>推荐工具</th><th>原因</th></tr></thead><tbody><tr><td>快速 add/commit/push</td><td>命令行</td><td>几秒敲完，不用摸鼠标</td></tr><tr><td>查看文件差异</td><td>VS Code</td><td>左右对比视图，直观</td></tr><tr><td>解决合并冲突</td><td>VS Code</td><td>一键选版本，不用手删标记</td></tr><tr><td>rebase / cherry-pick</td><td>命令行</td><td>VS Code 对这类操作支持有限</td></tr><tr><td>查看文件历史</td><td>VS Code + Git History</td><td>可视化时间线</td></tr></tbody></table><blockquote><p>💡 不用二选一——日常 add/commit/push 走命令行，遇到冲突打开 VS Code，各取所长。</p></blockquote><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>在 VS Code 里打开项目，通过源代码管理面板完成一次 add → commit → push</li><li>修改一个文件，在 VS Code 的左右对比视图中查看差异，然后丢弃修改</li><li>故意制造一个合并冲突，用 VS Code 的 Accept Current / Incoming Change 按钮解决</li><li>安装 Git History 插件，查看某个文件的历史提交记录，用 Reset --soft 回退到上一个版本</li></ol>',39)])])}const u=e(a,[["render",i]]);export{p as __pageData,u as default};
